  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B004",
      "proposed_laureates": ["Rashid Sunyaev"],
      "assessment": {
        "nobel_worthiness": "The Sunyaev-Zel'dovich effects turned CMB distortions by hot plasma into enduring tools for studying galaxy clusters and the expansion history of the Universe.",
        "attribution": "Sunyaev's contribution to the theoretical prediction and its cosmological development is central. The prediction was joint with Yakov Zel'dovich, who is deceased and cannot receive the prize.",
        "maturity": "The effects have been observed and used across generations of CMB and cluster surveys; their scientific importance is well established.",
        "uncertainties": ["The discovery was joint, and the candidate framing gives credit only to Sunyaev; the exact balance of credit between the original prediction and later development merits review."]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B005",
      "proposed_laureates": ["Heino Falcke", "James M. Moran", "Sheperd S. Doeleman"],
      "assessment": {
        "nobel_worthiness": "Horizon-scale black-hole imaging made strong-field gravity accessible to direct observation and produced a striking new test of general relativity.",
        "attribution": "Falcke's early imaging proposal, Moran's foundational interferometry work, and Doeleman's leadership in demonstrating and organizing the global VLBI observations form a defensible core attribution.",
        "maturity": "The M87* result and the later Sgr A* images establish a durable observational capability, with independent analyses and extensive follow-up.",
        "uncertainties": ["The Event Horizon Telescope is a large international collaboration, so selecting three individuals risks omitting substantial contributions to instrumentation, analysis, and observing."]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B002",
      "proposed_laureates": ["Peter F. Moulton", "Ursula Keller", "Wilson Sibbett"],
      "assessment": {
        "nobel_worthiness": "The titanium-sapphire laser and practical passive mode-locking methods made powerful, tunable femtosecond pulses broadly available and enabled major advances in ultrafast science.",
        "attribution": "Moulton's gain medium and the complementary mode-locking advances associated with Keller and Sibbett make a credible three-person account of the enabling technology.",
        "maturity": "The sources and techniques have been used and refined for decades, with their central role in ultrafast optics firmly established.",
        "uncertainties": ["The development was distributed across groups, and the relative priority and scope of credit for the different mode-locking techniques need careful historical assessment."]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B011",
      "proposed_laureates": ["Michael Berry", "Yakir Aharonov"],
      "assessment": {
        "nobel_worthiness": "The Aharonov-Bohm effect and Berry phase revealed that quantum phases have physical consequences and became foundational concepts across physics.",
        "attribution": "Aharonov's work established the significance of potentials and phase in quantum mechanics; Berry identified and developed the general geometric phase framework.",
        "maturity": "Both effects have extensive experimental confirmation and broad, lasting influence in quantum and condensed-matter physics.",
        "uncertainties": ["The candidate combines related but distinct discoveries; the scope of a prize joining them would need to be made clear."]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B020",
      "proposed_laureates": ["Alessandra Buonanno", "Frans Pretorius", "Thibault Damour"],
      "assessment": {
        "nobel_worthiness": "The effective-one-body framework and numerical-relativity breakthroughs made accurate predictions for binary black-hole mergers possible and helped turn gravitational-wave astronomy into a precision science.",
        "attribution": "Buonanno and Damour developed the effective-one-body approach, while Pretorius achieved the breakthrough simulation of merging black holes. These are distinct contributions that strongly complemented one another.",
        "maturity": "The methods have been validated by observed gravitational-wave signals and are now central tools for interpreting compact-binary data.",
        "uncertainties": ["The credit for successful simulations and waveform modeling extends to a broad community, and the proposed framing combines theory and computational breakthroughs."]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B008",
      "proposed_laureates": ["Christian Spiering", "Francis Halzen"],
      "assessment": {
        "nobel_worthiness": "IceCube established high-energy neutrinos as a new means of observing the Universe, opening a window on energetic astrophysical processes that light alone cannot provide.",
        "attribution": "Halzen provided sustained scientific leadership and helped bring the detector concept to realization; Spiering made major contributions to the field and the international effort behind neutrino astronomy.",
        "maturity": "The diffuse astrophysical neutrino flux is established, and the detector has produced a sustained body of results.",
        "uncertainties": ["The sources responsible for most of the flux remain incompletely identified, and the detector and discoveries depended on a very large collaboration."]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B043",
      "proposed_laureates": ["Alexei Kitaev", "Andrew M. Steane", "Peter W. Shor"],
      "assessment": {
        "nobel_worthiness": "Quantum error correction and fault tolerance showed how quantum information can be protected despite noise, making scalable quantum computation physically conceivable.",
        "attribution": "Shor and Steane introduced influential early quantum codes, while Kitaev developed topological approaches with lasting importance for fault tolerance.",
        "maturity": "The principles are well established and experimental error correction has advanced substantially, though large-scale fault-tolerant computation remains a goal.",
        "uncertainties": ["The field has many foundational contributors, and the ultimate practical reach of fault-tolerant quantum computing is not yet settled."]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B033",
      "proposed_laureates": ["Jocelyn Bell Burnell"],
      "assessment": {
        "nobel_worthiness": "The discovery of pulsars revealed neutron stars as observable astrophysical objects and opened a new precision tool for studying gravity and dense matter.",
        "attribution": "Bell Burnell identified the first pulsars in the radio data and recognized the significance of the signal, making her contribution decisive.",
        "maturity": "Pulsars have been studied for decades and remain central to astrophysics; the discovery's importance is beyond dispute.",
        "uncertainties": ["The original discovery was made within a research group, so the historical record and the distinction between discovery, supervision, and subsequent interpretation require careful review."]
      }
    }
  ]
